CREATE TYPE public.advert_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.advert_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own roles" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_advert_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin'); $$;
REVOKE ALL ON FUNCTION public.is_advert_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_advert_admin() TO authenticated;
CREATE TABLE public.marketplace_adverts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL DEFAULT auth.uid(), business_name text NOT NULL CHECK (char_length(business_name) BETWEEN 1 AND 100), title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120), image_url text NOT NULL CHECK (image_url LIKE 'https://%'), destination_url text NOT NULL CHECK (destination_url LIKE 'https://%'), placement text NOT NULL CHECK (placement IN ('sidebar','banner')), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','paused')), review_note text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), CHECK (ends_at > starts_at));
GRANT SELECT, INSERT ON public.marketplace_adverts TO authenticated;
GRANT UPDATE(status, review_note) ON public.marketplace_adverts TO authenticated;
GRANT SELECT(id,business_name,title,image_url,destination_url,placement,starts_at,ends_at,created_at) ON public.marketplace_adverts TO anon;
GRANT ALL ON public.marketplace_adverts TO service_role;
ALTER TABLE public.marketplace_adverts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public active approved adverts" ON public.marketplace_adverts FOR SELECT TO anon USING (status = 'approved' AND starts_at <= now() AND ends_at > now());
CREATE POLICY "Owners and admins read adverts" ON public.marketplace_adverts FOR SELECT TO authenticated USING (owner_id = auth.uid() OR public.is_advert_admin());
CREATE POLICY "Merchant submits pending advert" ON public.marketplace_adverts FOR INSERT TO authenticated WITH CHECK (owner_id = auth.uid() AND status = 'pending' AND review_note = '');
CREATE POLICY "Only admins moderate adverts" ON public.marketplace_adverts FOR UPDATE TO authenticated USING (public.is_advert_admin()) WITH CHECK (public.is_advert_admin());
CREATE INDEX marketplace_adverts_delivery_idx ON public.marketplace_adverts (placement, status, starts_at, ends_at);
CREATE INDEX marketplace_adverts_owner_idx ON public.marketplace_adverts (owner_id);